function drawRock(e){let x=e.x*C,y=e.y*C;ctx.fillStyle='#303c38';ctx.fillRect(x+8,y+18,26,17);ctx.fillStyle='#798078';ctx.fillRect(x+11,y+12,21,19);ctx.fillStyle='#a0a092';ctx.fillRect(x+17,y+7,12,12);ctx.fillStyle='#c2b9a1';ctx.fillRect(x+19,y+8,7,3);ctx.fillStyle='#4a554f';ctx.fillRect(x+8,y+27,9,5)}
function drawBuilding(e){let x=e.x*C,y=e.y*C;ctx.fillStyle='#263026';ctx.fillRect(x+4,y+31,32,7);
if(e.type==='town'){ctx.fillStyle='#8c623d';ctx.fillRect(x+5,y+18,30,18);ctx.fillStyle='#b18651';ctx.fillRect(x+9,y+13,22,22);ctx.fillStyle='#573b2c';ctx.fillRect(x+6,y+7,28,12);ctx.fillStyle='#a45037';ctx.fillRect(x+7,y+5,26,6);ctx.fillStyle='#e2bf78';ctx.fillRect(x+18,y+23,6,12);ctx.fillStyle='#f0d48b';ctx.fillRect(x+22,y+2,2,13);ctx.fillStyle='#b43e32';ctx.fillRect(x+24,y+3,10,6)}
else if(e.type==='outpost'){ctx.fillStyle='#79513a';ctx.fillRect(x+8,y+18,25,17);ctx.fillStyle='#574033';ctx.fillRect(x+5,y+12,31,9);ctx.fillStyle='#3d332b';ctx.fillRect(x+11,y+8,19,7);ctx.fillStyle='#bd503b';ctx.fillRect(x+22,y+3,2,12);ctx.fillStyle='#e05e45';ctx.fillRect(x+24,y+4,10,6)}
else if(e.type==='house'){ctx.fillStyle='#b88a51';ctx.fillRect(x+7,y+17,27,19);ctx.fillStyle='#805331';ctx.fillRect(x+4,y+11,33,10);ctx.fillStyle='#d2a667';ctx.fillRect(x+11,y+20,7,7);ctx.fillStyle='#47372a';ctx.fillRect(x+23,y+25,6,11)}
else if(e.type==='farm'){ctx.fillStyle='#58432b';ctx.fillRect(x+4,y+14,32,22);ctx.fillStyle='#bd9956';for(let i=0;i<4;i++){ctx.fillRect(x+7,y+17+i*5,26,2);for(let j=0;j<5;j++)ctx.fillRect(x+9+j*5,y+15+i*5,2,4)}ctx.fillStyle='#648244';ctx.fillRect(x+4,y+10,32,4)}
else if(e.type==='barracks'){ctx.fillStyle='#94734a';ctx.fillRect(x+5,y+15,31,21);ctx.fillStyle='#554436';ctx.fillRect(x+3,y+10,35,10);ctx.fillStyle='#7d5539';ctx.fillRect(x+13,y+20,15,16);ctx.fillStyle='#d4ba76';ctx.fillRect(x+19,y+22,3,7)}
else{ctx.fillStyle='#8b744d';ctx.fillRect(x+11,y+17,20,19);ctx.fillStyle='#71573d';ctx.fillRect(x+8,y+12,26,8);ctx.fillStyle='#a38c5d';ctx.fillRect(x+14,y+3,14,12);ctx.fillStyle='#c04e3a';ctx.fillRect(x+16,y+1,11,4);ctx.fillStyle='#e5c779';ctx.fillRect(x+19,y+22,3,5)}
}
function drawUnit(e){let x=e.x*C,y=e.y*C;let enemy=e.owner==='red';ctx.fillStyle='#172019';ctx.fillRect(x+10,y+32,20,5);if(e.type==='villager'){ctx.fillStyle='#bb9b69';ctx.fillRect(x+14,y+14,13,16);ctx.fillStyle='#dfbd82';ctx.fillRect(x+15,y+9,11,8);ctx.fillStyle='#553e2d';ctx.fillRect(x+14,y+8,13,4);ctx.fillStyle='#4d6142';ctx.fillRect(x+13,y+22,15,9);ctx.fillStyle='#efe0b3';ctx.fillRect(x+14,y+32,5,4);ctx.fillRect(x+23,y+32,5,4);ctx.fillStyle='#9e8e65';ctx.fillRect(x+29,y+17,3,15)}else{ctx.fillStyle=enemy?'#824235':'#9a8054';ctx.fillRect(x+11,y+14,19,17);ctx.fillStyle=enemy?'#bb5741':'#a9a18a';ctx.fillRect(x+13,y+8,15,11);ctx.fillStyle=enemy?'#4c3730':'#ded4b6';ctx.fillRect(x+15,y+10,11,5);ctx.fillStyle=enemy?'#aa3e32':'#4c6680';ctx.fillRect(x+11,y+21,19,8);ctx.fillStyle=enemy?'#502f2b':'#e2dbc0';ctx.fillRect(x+15,y+31,5,5);ctx.fillRect(x+24,y+31,5,5);ctx.fillStyle='#bdb79f';ctx.fillRect(x+29,y+10,2,23);ctx.fillStyle='#d0c595';ctx.fillRect(x+30,y+10,4,2)}if(e.selected){ctx.strokeStyle='#f0d27c';ctx.lineWidth=2;ctx.strokeRect(x+6,y+5,29,33)}if(e.hp<e.max){ctx.fillStyle='#31291f';ctx.fillRect(x+8,y+2,25,3);ctx.fillStyle=enemy?'#df6350':'#92cc71';ctx.fillRect(x+8,y+2,25*Math.max(0,e.hp/e.max),3)}}
function draw(){ctx.clearRect(0,0,W,H);for(let y=0;y<R;y++)for(let x=0;x<C;x++)tile(x,y);for(const d of decor){let x=d.x*C,y=d.y*C;ctx.fillStyle=d.kind===0?'#d4c473':d.kind===1?'#e7d2a0':'#72905b';ctx.fillRect(x+13,y+17,3,3);ctx.fillRect(x+21,y+25,2,2)}for(const e of entities.filter(e=>e.type==='tree'||e.type==='rock'))e.type==='tree'?drawTree(e):drawRock(e);for(const e of entities.filter(e=>!['tree','rock','decoration'].includes(e.type)).sort((a,b)=>a.y-b.y)){if(['town','outpost','house','farm','barracks','tower'].includes(e.type))drawBuilding(e);else drawUnit(e);if(e.selected&&['town','outpost','house','farm','barracks','tower'].includes(e.type)){ctx.strokeStyle='#e4c66e';ctx.lineWidth=2;ctx.strokeRect(e.x*C+3,e.y*C+2,34,37)}}for(const fx of effects){ctx.fillStyle=fx.color;ctx.font='bold 14px monospace';ctx.textAlign='center';ctx.fillText(fx.text,fx.x*C+20,fx.y*C+8-fx.life*12)}if(game.box){ctx.strokeStyle='#e7d278';ctx.setLineDash([5,3]);ctx.strokeRect(game.box.x,game.box.y,game.box.w,game.box.h);ctx.setLineDash([])}}

