function draw(){ctx.clearRect(0,0,W,H);for(let y=0;y<R;y++)for(let x=0;x<C;x++)tile(x,y);for(const d of decor){let x=d.x*C,y=d.y*C;ctx.fillStyle=d.kind===0?'#d4c473':d.kind===1?'#e7d2a0':'#72905b';ctx.fillRect(x+13,y+17,3,3);ctx.fillRect(x+21,y+25,2,2)}for(const e of entities.filter(e=>e.type==='tree'||e.type==='rock'))e.type==='tree'?drawTree(e):drawRock(e);for(const e of entities.filter(e=>!['tree','rock','decoration'].includes(e.type)).sort((a,b)=>a.y-b.y)){if(['town','outpost','house','farm','barracks','tower'].includes(e.type))drawBuilding(e);else drawUnit(e);if(e.selected&&['town','outpost','house','farm','barracks','tower'].includes(e.type)){ctx.strokeStyle='#e4c66e';ctx.lineWidth=2;ctx.strokeRect(e.x*C+3,e.y*C+2,34,37)}}for(const fx of effects){ctx.fillStyle=fx.color;ctx.font='bold 14px monospace';ctx.textAlign='center';ctx.fillText(fx.text,fx.x*C+20,fx.y*C+8-fx.life*12)}if(game.box){ctx.strokeStyle='#e7d278';ctx.setLineDash([5,3]);ctx.strokeRect(game.box.x,game.box.y,game.box.w,game.box.h);ctx.setLineDash([])}}
const cost={house:{wood:60},farm:{wood:45},barracks:{wood:90,stone:30},tower:{wood:55,stone:40}};
const label={house:'House',farm:'Farm',barracks:'Barracks',tower:'Watchtower',town:'Town center',outpost:'Redfang outpost',villager:'Villager',swordsman:'Swordsman',enemy:'Redfang raider'};
function log(text,notice=false){let el=document.createElement('div');el.className='log-line'+(notice?' notice':'');el.textContent=text;let box=document.getElementById('log');box.prepend(el);while(box.children.length>5)box.lastChild.remove()}
function pop(msg,color='#e7cf87'){effects.push({x:Math.min(C-1,Math.max(0,msg.x)),y:Math.min(R-1,Math.max(0,msg.y)),text:msg.text,color,life:0})}
function updateUI(){for(let r of ['food','wood','stone','gold'])document.getElementById(r).textContent=Math.floor(game[r]);document.getElementById('pop').textContent=`POPULATION ${game.population} / ${game.popCap}`;document.getElementById('objective-progress').style.width=entities.some(e=>e.type==='outpost')?'0%':'100%';document.getElementById('objective-count').textContent=entities.some(e=>e.type==='outpost')?'0 / 1':'1 / 1';document.getElementById('clock').textContent=`☀ DAY ${game.day} · ${String(Math.floor(game.time/60)%24).padStart(2,'0')}:${String(Math.floor(game.time%60)).padStart(2,'0')}`;document.querySelectorAll('.build-btn').forEach(b=>{let c=cost[b.dataset.build];b.disabled=Object.keys(c).some(k=>game[k]<c[k])});}
function setSelection(arr){game.selected.forEach(e=>e.selected=false);game.selected=arr;arr.forEach(e=>e.selected=true);let holder=document.getElementById('selection');document.getElementById('sel-count').textContent=arr.length?`${arr.length} UNIT${arr.length>1?'S':''}`:'—';if(!arr.length){holder.innerHTML='<div class="select-empty">Choose a unit or building<br>to see its orders.</div>';return}let e=arr[0],icon={villager:'♟',swordsman:'⚔',town:'♜',outpost:'⚑',house:'⌂',farm:'♧',barracks:'⚔',tower:'♜',enemy:'⚔'}[e.type]||'♟';let title=arr.length>1?`${arr.length} selected`:label[e.type];let actions='';if(e.type==='villager')actions='<div class="cmd-row"><button class="cmd" data-order="gather">⛏ Gather</button><button class="cmd" data-order="stop">■ Stop</button></div>';if(e.type==='town')actions='<div class="cmd-row"><button class="cmd" id="quick-villager">♟ Train villager · 50 food</button></div>';holder.innerHTML=`<div class="selected-row"><div class="unit-icon">${icon}</div><div><div class="unit-name">${title}</div><div class="unit-desc">${e.task?`Working · ${e.task}`:e.order?'On the move':'Awaiting orders'}</div></div></div><div class="health-row"><span>VITALITY</span><span>${Math.ceil(e.hp)} / ${e.max}</span></div><div class="healthbar"><span style="width:${100*e.hp/e.max}%"></span></div>${actions}`;holder.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{if(b.dataset.order==='stop')game.selected.forEach(u=>{u.order=null;u.task=null});else log('Right-click a tree or stone to gather.');refreshSelection()});let q=document.getElementById('quick-villager');if(q)q.onclick=trainVillager}
function refreshSelection(){setSelection(game.selected.slice())}
function trainVillager(){if(game.food<50||game.population>=game.popCap){log(game.food<50?'Not enough food.':'Build a house to grow your population.',true);return}game.food-=50;game.population++;let town=entities.find(e=>e.type==='town');entities.push(ent('villager',town.x+1,town.y+2));log('A new villager joins your settlement.');updateUI();refreshSelection()}
function nearestResource(x,y,type){return entities.filter(e=>e.type===type).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0]}
function gather(v,target){if(!target)return;v.task=target.type;v.target=target;v.order={x:target.x,y:target.y};v.harvest=0}
function moveTo(e,x,y){e.order={x:Math.max(1,Math.min(C-2,x)),y:Math.max(1,Math.min(R-2,y))};e.task=null;e.target=null}
function interact(x,y){let tx=Math.floor(x/C),ty=Math.floor(y/C);if(game.buildMode){let type=game.buildMode;let coll=entities.some(e=>Math.abs(e.x-tx)<1.2&&Math.abs(e.y-ty)<1.2);if(coll||terrain[ty]?.[tx]!==0){log('That ground is not suitable for a building.',true);return}let c=cost[type];if(Object.keys(c).some(k=>game[k]<c[k])){log('Not enough resources.',true);return}if(!game.selected.some(e=>e.type==='villager')){log('Select a villager to build.',true);return}for(let k in c)game[k]-=c[k];let b=ent(type,tx,ty,{hp:35,max:type==='house'?180:type==='barracks'?260:type==='farm'?120:200,building:true});entities.push(b);game.selected.filter(e=>e.type==='villager').forEach(v=>{v.order={x:tx,y:ty};v.task='build';v.target=b});game.buildMode=null;document.querySelectorAll('.build-btn').forEach(b=>b.classList.remove('active'));log(`${label[type]} construction started.`);updateUI();return}
let nearby=entities.filter(e=>e.type!=='decoration'&&Math.abs(e.x*C+20-x)<20&&Math.abs(e.y*C+20-y)<20).sort((a,b)=>Math.hypot(a.x*C+20-x,a.y*C+20-y)-Math.hypot(b.x*C+20-x,b.y*C+20-y))[0];if(nearby&&nearby.owner==='blue'){setSelection([nearby]);return}if(nearby&&nearby.owner==='red'){setSelection([nearby]);return}setSelection([])}
let drag=null;
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);let r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;if(e.button===2){let tx=Math.floor(mouse.x/C),ty=Math.floor(mouse.y/C),res=entities.find(e=>(e.type==='tree'||e.type==='rock')&&Math.abs(e.x-tx)<1&&Math.abs(e.y-ty)<1);for(let u of game.selected){if(u.type==='villager'&&res)gather(u,res);else if(u.type==='swordsman'||u.type==='villager')moveTo(u,tx,ty)}if(res)log(`Gathering ${res.type==='tree'?'wood':'stone'}.`);return}drag={x:mouse.x,y:mouse.y,moved:false};});
canvas.addEventListener('pointermove',e=>{let r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;if(drag&&Math.hypot(mouse.x-drag.x,mouse.y-drag.y)>7)drag.moved=true;if(drag&&drag.moved)game.box={x:Math.min(drag.x,mouse.x),y:Math.min(drag.y,mouse.y),w:Math.abs(mouse.x-drag.x),h:Math.abs(mouse.y-drag.y)}});
