function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function damage(target,n){target.hp-=n;if(target.hp<=0){let idx=entities.indexOf(target);if(idx>=0)entities.splice(idx,1);if(target.type==='outpost'){game.won=true;log('The Redfang outpost has fallen! The Greenward is yours.',true);document.getElementById('tip').innerHTML='<b>VICTORY</b> · The Greenward is yours!'}else if(target.owner==='blue'){log(`${label[target.type]||'Your unit'} has fallen.`,true);if(['villager','swordsman'].includes(target.type))game.population=Math.max(0,game.population-1)}}}
function attack(attacker,target,dt){attacker.cool=(attacker.cool||0)-dt;if(attacker.cool<=0){damage(target,attacker.attack||10);attacker.cool=attacker.type==='outpost'?.95:.8}}
function tick(dt){if(game.paused)return;game.time+=dt;game.tick+=dt;if(game.time>=1440){game.time=0;game.day++}
for(const e of entities.slice()){if(e.type==='farm'){e.harvest=(e.harvest||0)+dt;if(e.harvest>1.5){game.food+=2;e.harvest=0}}
if(e.building){let builders=entities.filter(u=>u.task==='build'&&u.target===e);if(builders.length){e.hp=Math.min(e.max,e.hp+dt*13*builders.length);if(e.hp>=e.max){e.building=false;builders.forEach(v=>{v.task=null;v.target=null;v.order=null});if(e.type==='house'){game.popCap+=5;log('House complete — population capacity increased.',true)}else log(`${label[e.type]} complete.`)}}}
if(e.type==='villager'&&e.task==='wood'||e.type==='villager'&&e.task==='rock'){let target=e.target;if(!target||!entities.includes(target)){e.task=null;e.target=null;continue}if(distance(e,target)>1.15){let dx=target.x-e.x,dy=target.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else{e.harvest=(e.harvest||0)+dt;if(e.harvest>1.15){e.harvest=0;game[e.task==='wood'?'wood':'stone']+=8;pop({x:e.x,y:e.y,text:'+8'},'#e7cf87')}}}
if(e.task==='farm'){e.task=null}
